1	#!/usr/bin/env node
2	/**
3	 * Token usage audit — flags a raw hex colour / px / rem / em literal in an override component
4	 * or theme recipe, where a Zimmermann token (a foundation constant, a var(--zimm-*) reference,
5	 * or a Chakra prop resolving through a registered scale) should be used instead.
6	 *
7	 * Usage:
8	 *   node scripts/auditTokenUsage.mjs
9	 *
10	 * Scope: overrides/app/components/** and overrides/app/theme/components/** — .ts/.tsx/.scss.
11	 * Deliberately excludes:
12	 *   - overrides/app/theme/foundation/ — not under either scan root; these files ARE the source
13	 *     of truth, so a raw value there is the point, not a violation.
14	 *   - *.test.ts(x) and *.stories.tsx — test assertions and Storybook demo code routinely need
15	 *     illustrative/representative raw values that aren't "a hardcoded design value shipped to
16	 *     production" in the sense this audit cares about (testing.md already treats these
17	 *     differently from production styling rigor).
18	 *
19	 * A match is downgraded from a failure to an ACKNOWLEDGED exception (still printed, does not
20	 * affect the exit code) when the contiguous non-blank block of lines ending at the match — i.e.
21	 * the match's own line plus every line above it up to the nearest blank line or file start —
22	 * contains "provisional", "pending", "placeholder", or an explicit "audit-allow". This is the
23	 * exact vocabulary this codebase already uses for every documented raw-value exception today
24	 * (e.g. zimmButton.css.ts's BTN_HEIGHT_LG/BTN_HEIGHT_SM/BTN_PADDING_Y, footer.css.ts's
25	 * SPACE_SECTION/SIZE_COL_SUB/SIZE_COL_MAP). Reading the existing explanatory comment as the
26	 * allow-list entry avoids a second, separately-maintained list that would drift from the code
27	 * the moment either one changes.
28	 *
29	 * The "nearest blank line" boundary, not a fixed line count, matters: this codebase's real
30	 * exception comments are often a shared multi-line block covering several sibling declarations
31	 * (footer.css.ts's four provisional constants share one comment), or wrap the marker word
32	 * itself across a line break (zimmSubscribeSection.css.ts had "...52/40. Pending\n// Kiera."
33	 * — "Pending" and "Kiera" on different lines). A fixed N-line window missed both shapes during
34	 * this script's own first calibration pass against the real codebase.
35	 *
36	 * This is a line-based grep, not an AST parse — matches
37	 * .claude/rules/overrideStyling.md's own framing ("it greps for exactly this"). A real
38	 * false-positive class this cannot fully rule out: a hex-looking string in a non-colour
39	 * context (e.g. a URL fragment that happens to be 3-8 hex characters) would still be flagged;
40	 * mark it with `// audit-allow: <reason>` rather than trying to make the regex smarter.
41	 *
42	 * Not wired into CI yet — see overrideStyling.md's note on why (someone needs to own triaging
43	 * false positives on a real run first).
44	 */
45	
46	import { readFileSync, readdirSync, existsSync } from 'fs';
47	import { join, extname, relative, dirname } from 'path';
48	import { fileURLToPath } from 'url';
49	
50	const __dirname = dirname(fileURLToPath(import.meta.url));
51	const ROOT = join(__dirname, '..');
52	const APP = join(ROOT, 'overrides/app');
53	
54	const SCAN_ROOTS = [join(APP, 'components'), join(APP, 'theme/components')];
55	const SCAN_EXTENSIONS = new Set(['.ts', '.tsx', '.scss']);
56	
57	const HEX_RE = /#[0-9a-fA-F]{3,8}\b/g;
58	const UNIT_RE = /\b\d+(?:\.\d+)?(?:rem|em|px)\b/g;
59	const EXCEPTION_MARKER_RE = /provisional|pending|placeholder|audit-allow/i;
60	
61	const isExcludedFile = (filePath) =>
62	  filePath.endsWith('.test.ts') || filePath.endsWith('.test.tsx') || filePath.endsWith('.stories.tsx');
63	
64	function walk(dir, files = []) {
65	  for (const entry of readdirSync(dir, { withFileTypes: true })) {
66	    const full = join(dir, entry.name);
67	    if (entry.isDirectory()) {
68	      walk(full, files);
69	    } else if (SCAN_EXTENSIONS.has(extname(entry.name)) && !isExcludedFile(full)) {
70	      files.push(full);
71	    }
72	  }
73	  return files;
74	}
75	
76	/**
77	 * Strips `//` and `/* *\/` comment content from a line so a Figma hex value or px measurement
78	 * mentioned in prose doesn't get flagged as a code violation. Tracks block-comment state across
79	 * lines via the mutable `state` object the caller owns. `//` is only treated as a comment start
80	 * when not immediately preceded by `:` — otherwise `'https://wa.me/...'` string literals (real
81	 * content in this codebase's Contentful fixtures) would truncate the line early.
82	 */
83	function stripComments(line, state) {
84	  let result = '';
85	  let i = 0;
86	  while (i < line.length) {
87	    if (state.inBlockComment) {
88	      const end = line.indexOf('*/', i);
89	      if (end === -1) return result;
90	      i = end + 2;
91	      state.inBlockComment = false;
92	      continue;
93	    }
94	    if (line[i] === '/' && line[i + 1] === '/' && line[i - 1] !== ':') break;
95	    if (line[i] === '/' && line[i + 1] === '*') {
96	      state.inBlockComment = true;
97	      i += 2;
98	      continue;
99	    }
100	    result += line[i];
101	    i += 1;
102	  }
103	  return result;
104	}
105	
106	function scanFile(filePath) {
107	  const relPath = relative(ROOT, filePath);
108	  const lines = readFileSync(filePath, 'utf8').split('\n');
109	  const state = { inBlockComment: false };
110	  const findings = [];
111	
112	  lines.forEach((rawLine, idx) => {
113	    const lineNo = idx + 1;
114	    const code = stripComments(rawLine, state);
115	
116	    const matches = [...code.matchAll(HEX_RE), ...code.matchAll(UNIT_RE)];
117	    if (matches.length === 0) return;
118	
119	    let contextStart = idx;
120	    while (contextStart > 0 && lines[contextStart - 1].trim() !== '') contextStart -= 1;
121	    const context = lines.slice(contextStart, idx + 1).join('\n');
122	    const acknowledged = EXCEPTION_MARKER_RE.test(context);
123	
124	    for (const match of matches) {
125	      findings.push({ file: relPath, line: lineNo, value: match[0], acknowledged, text: rawLine.trim() });
126	    }
127	  });
128	
129	  return findings;
130	}
131	
132	const files = SCAN_ROOTS.filter(existsSync).flatMap((root) => walk(root));
133	const allFindings = files.flatMap(scanFile);
134	const failures = allFindings.filter((f) => !f.acknowledged);
135	const acknowledged = allFindings.filter((f) => f.acknowledged);
136	
137	console.log('Token usage audit');
138	console.log('==================');
139	console.log(`Scanned ${files.length} file(s) under overrides/app/components/ and overrides/app/theme/components/\n`);
140	
141	if (failures.length > 0) {
142	  console.log(`❌ ${failures.length} raw value(s) with no acknowledged exception:\n`);
143	  for (const f of failures) {
144	    console.log(`  ${f.file}:${f.line}  '${f.value}'`);
145	    console.log(`    ${f.text}`);
146	  }
147	  console.log('\n  Reach for a token instead — var(--zimm-color-*) for hex, var(--zimm-scale-*) for px/rem/em.');
148	  console.log(
149	    '  If this genuinely has no token yet (pending UI-designer sign-off), name it as a constant\n' +
150	      '  with a comment containing "provisional"/"pending"/"placeholder", or add "audit-allow: <reason>".',
151	  );
152	}
153	
154	if (acknowledged.length > 0) {
155	  console.log(`\n✓ ${acknowledged.length} raw value(s) with an acknowledged exception (not failing):`);
156	  for (const f of acknowledged) {
157	    console.log(`  ${f.file}:${f.line}  '${f.value}'`);
158	  }
159	}
160	
161	console.log(
162	  failures.length > 0
163	    ? `\n${failures.length} unacknowledged violation(s) found.`
164	    : '\nNo unacknowledged raw hex/px/rem/em literals found.',
165	);
166	
167	process.exit(failures.length > 0 ? 1 : 0);
168

1	import React from 'react';
2	import { Global, css } from '@emotion/react';
3	import { zimmTokens } from './foundation/zimmTokens';
4	
5	// Injects the --zimm-* custom properties onto :root via a raw Emotion <Global>.
6	//
7	// Deliberately NOT Chakra's styles.global: Chakra's style processor mangles quoted
8	// font-family values (verified — "'Futura Round', 'Century Gothic', sans-serif"
9	// collapses to a single family), which would break the --zimm-font-family-* vars.
10	// A raw Emotion <Global> preserves them.
11	//
12	// Rendered in the app by _app-config/index.tsx AND in Storybook by
13	// .storybook/preview.tsx, so the .zimm-* global classes and the var(--zimm-*)
14	// component overrides resolve identically in both. Kept as one shared definition
15	// so the two mount points cannot drift.
16	export const zimmRootVarsCss = css`
17	  :root {
18	    ${Object.entries(zimmTokens)
19	      .map(([k, v]) => `${k}:${v}`)
20	      .join(';')}
21	  }
22	`;
23	
24	/** Injects the --zimm-* :root custom properties. Render once, high in the tree. */
25	export function ZimmTokensGlobal(): React.ReactElement {
26	  return <Global styles={zimmRootVarsCss} />;
27	}
