/**
 * SFCC ↔ Contentful mapping constants.
 *
 * Locale/site mapping (SUPPORTED_LOCALES, SITE_LOCALES) comes from
 * contentfulMapping.generated.ts — regenerate via
 * `npm run sync:regional-config`, which derives it from the same SCAPI
 * fetch that populates config/sites.generated.js. The environment ID is
 * injected per MRT tier via the CONTENTFUL_ENVIRONMENT_ID env var; this
 * file provides the canonical reference for what each tier maps to.
 *
 * Tier topology (DEV → TEST → OMS INT → STAGE → UAT → PRODUCTION):
 *   dev | test | sit | staging | uat | master (via 'production' alias)
 */

import { SITE_LOCALES as GENERATED_SITE_LOCALES, SUPPORTED_LOCALES } from './contentfulMapping.generated';

// ── Locale mapping ────────────────────────────────────────────────────────────

export { SUPPORTED_LOCALES };

export type SupportedLocale = (typeof SUPPORTED_LOCALES)[number];

/** The Contentful default locale — all others fall back to this. */
export const DEFAULT_LOCALE: SupportedLocale = 'en';

/**
 * Maps SFCC site IDs to the locale codes they serve.
 * Matches the l10n.supportedLocales configuration in config/sites.js.
 */
export const SITE_LOCALES = GENERATED_SITE_LOCALES as Record<string, readonly SupportedLocale[]>;

// ── Environment mapping ───────────────────────────────────────────────────────

