      </chakra.div>

      {enableNameCapture && (
        <ZimmSubscribeModal
          isOpen={modalOpen}
          onClose={closeModal}
          onSubmit={handleModalSubmit}
          privacyPolicyHref={privacyPolicyHref}
        />
      )}
    </div>
  );
};

